mapper.select:
select coalesce(max(version_no), 0)
from wf_bpmn_extension_version
where extension_id = #{extensionId}

mapper.update:
update wf_bpmn_extension
set status = #{status}, update_by = #{updateBy}, update_time = current_timestamp(3)
where extension_id = #{extensionId}

mapper.delete:
delete from wf_bpmn_extension
where extension_id = #{extensionId}
  and status = 'DISABLED'
